class NaiveBayesClassifier:
    def __init__(self, prior=None):
        self.prior = prior if prior is not None else {}

    def fit(self, X, y):
        self.prior = {}
        for c in np.unique(y):
            self.prior[c] = np.mean(y == c)
            self.prior[c]

