            for feature in range(X.shape[1]):
                self.p[c][feature] = norm.fit(X[y == c, feature])[0]

    def predict(self, X):
        predictions = []
        for x in X:
            posteriors = {}
            for c in self.prior:
                posterior = self.prior[c]
                for feature in range(X.shape[1]):
                    posterior *= norm.pdf(x[feature], loc=self.p[c][feature], scale=1)
                posteriors[c] = posterior
            posteriors = {k: v * self.prior[k] for k, v in posteriors.items()}
            predictions.append(max(posteriors, key=posteriors.get))
